import pandas as pd

file_path = '/data/monthly_expense_ledger.xlsx'
df_raw = pd.read_excel(file_path, sheet_name=0, header=None)

counts = {}
for idx, row in df_raw.iterrows():
    col0 = row[0]
    if isinstance(col0, str) and col0.startswith('EXP-'):
        prog = row[2]
        if isinstance(prog, str):
            prog = prog.strip()
            counts[prog] = counts.get(prog, 0) + 1

print(counts)

import pandas as pd

file_path = '/data/monthly_expense_ledger.xlsx'
df_raw = pd.read_excel(file_path, sheet_name=0, header=None)

poshan_rows = []
for idx, row in df_raw.iterrows():
    col0 = row[0]
    if isinstance(col0, str) and col0.startswith('EXP-'):
        prog = row[2]
        if isinstance(prog, str):
            prog_clean = prog.strip()
            if prog_clean == 'Poshan Shakti':
                poshan_rows.append((idx, col0, prog_clean))

print('Count:', len(poshan_rows))
# Check any variants
variants = set()
for idx, row in df_raw.iterrows():
    col0 = row[0]
    if isinstance(col0, str) and col0.startswith('EXP-'):
        prog = row[2]
        if isinstance(prog, str) and 'Poshan' in prog:
            variants.add(repr(prog))
print('Variants:', variants)
